//! Provider 出网时的函数名编解码。

use std::collections::HashMap;

/// Convert a Core tool id to an OpenAI-compatible wire name.
pub fn to_wire_tool_name(name: &str) -> String {
    name.chars()
        .map(|character| match character {
            '.' | ':' => '_',
            character => character,
        })
        .collect()
}

/// Build a wire-name to original Core-id mapping.
///
/// Multiple different Core ids must not silently overwrite one another when
/// their wire names are identical.
pub fn mappings(names: &[&str]) -> Result<HashMap<String, String>, String> {
    let mut from_wire = HashMap::new();
    for original in names {
        let wire_name = to_wire_tool_name(original);
        if let Some(existing) = from_wire.get(&wire_name) {
            if existing != original {
                return Err(format!(
                    "tool name collision: {existing:?} and {original:?} both map to {wire_name:?}"
                ));
            }
        } else {
            from_wire.insert(wire_name, (*original).to_string());
        }
    }
    Ok(from_wire)
}

#[cfg(test)]
mod tests {
    use super::{mappings, to_wire_tool_name};

    #[test]
    fn encodes_openai_invalid_separators() {
        assert_eq!(to_wire_tool_name("fs.list"), "fs_list");
        assert_eq!(to_wire_tool_name("mcp:tool"), "mcp_tool");
    }

    #[test]
    fn preserves_legal_names() {
        assert_eq!(to_wire_tool_name("get_time"), "get_time");
    }

    #[test]
    fn mappings_round_trip_to_original_ids() {
        let names = ["fs.list", "mcp:tool", "get_time"];
        let map = mappings(&names).unwrap();

        assert_eq!(map.get("fs_list"), Some(&"fs.list".to_string()));
        assert_eq!(map.get("mcp_tool"), Some(&"mcp:tool".to_string()));
        assert_eq!(map.get("get_time"), Some(&"get_time".to_string()));
    }

    #[test]
    fn mappings_rejects_collisions() {
        assert!(mappings(&["fs.list", "fs_list"]).is_err());
    }

    #[test]
    fn duplicate_original_ids_are_allowed() {
        assert!(mappings(&["get_time", "get_time"]).is_ok());
    }
}

